//! Build script: scans `src/transitions/` for `pub struct` definitions
//! and generates the `E2ETransition` enum + `impl TransitionHandler` dispatch.
//!
//! ## How to add a new transition
//!
//! 1. Create `src/transitions/my_new_transition.rs`
//! 2. Define a `pub struct MyTransition { ... }`
//! 3. impl `TransitionHandler` for MyTransition
//! 4. Register module in `src/transitions/mod.rs`
//!
//! That's it — the enum and dispatch are auto-generated.

use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let out_dir = env::var("OUT_DIR").unwrap();
    let dest = Path::new(&out_dir).join("generated_transitions.rs");

    let transitions_dir = Path::new("src/transitions");
    let mut variants: Vec<String> = Vec::new();

    if transitions_dir.is_dir() {
        for entry in fs::read_dir(transitions_dir).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) != Some("rs") {
                continue;
            }
            let content = fs::read_to_string(&path).unwrap();
            for line in content.lines() {
                let trimmed = line.trim();
                if let Some(name) = parse_pub_struct_name(trimmed) {
                    variants.push(name);
                }
            }
        }
    }

    variants.sort();
    variants.dedup();

    if variants.is_empty() {
        panic!("No transition variants found in src/transitions/");
    }

    // CamelCase → snake_case for module paths
    fn to_snake(s: &str) -> String {
        let mut out = String::new();
        for (i, c) in s.chars().enumerate() {
            if c.is_uppercase() {
                if i > 0 {
                    out.push('_');
                }
                out.push(c.to_ascii_lowercase());
            } else {
                out.push(c);
            }
        }
        out
    }

    let uses: String = variants
        .iter()
        .map(|v| format!("use crate::transitions::{}::{};\n", to_snake(v), v))
        .collect();

    let enum_body: String = variants
        .iter()
        .map(|v| format!("    {v}({v}),\n"))
        .collect();

    let apply_arms: String = variants
        .iter()
        .map(|v| format!("            Self::{v}(inner) => inner.apply(ctx),\n"))
        .collect();

    let descr_arms: String = variants
        .iter()
        .map(|v| format!("            Self::{v}(inner) => inner.description(),\n"))
        .collect();

    let code = format!(
        "// AUTO-GENERATED by build.rs from src/transitions/\n\
         \n\
         {uses}\
         \n\
         pub enum E2ETransition {{\n\
         {enum_body}}}\n\
         \n\
         impl crate::TransitionHandler for E2ETransition {{\n\
             fn apply(&self, ctx: &mut crate::AppContext) -> anyhow::Result<()> {{\n\
                 match self {{\n\
         {apply_arms}                }}\n\
             }}\n\
         \n\
             fn description(&self) -> &'static str {{\n\
                 match self {{\n\
         {descr_arms}                }}\n\
             }}\n\
         }}\n"
    );

    fs::write(&dest, code).unwrap();
    println!("cargo:rerun-if-changed=src/transitions/");
    eprintln!(
        "build.rs: generated E2ETransition with {} variants: {:?}",
        variants.len(),
        variants
    );
}

fn parse_pub_struct_name(line: &str) -> Option<String> {
    let mut parts = line.split_whitespace();
    match (parts.next(), parts.next()) {
        (Some("pub"), Some("struct")) => {
            let name = parts.next()?;
            let name = name.trim_end_matches(|c: char| c == '{' || c == '(' || c == '<');
            if name.chars().next().map_or(false, |c| c.is_uppercase()) {
                Some(name.to_string())
            } else {
                None
            }
        }
        _ => None,
    }
}
